            for (match = 0; match < 15 &&
                 b->data[at + match] == (uint8_t)"fat acceptance "[match]; match++) {
            }
            if (match == 15) {
                b->data[at] = 'x';
                if (block_request(dev, 1, b->blk * BCACHE_BLOCK_SECTORS,
